"""
    Returns the smallest power of two which is >= x.
    """
def next_power_of_2(x: int) -> object {
    assert (isinstance(x, int) and (x > 0));
    res = 2 ** (x - 1).bit_length();
    assert (x <= res < (2 * x)) , f'{x}, {res}';
    return res;
}

"""
    only add when mapall option is used and
    "-q" and "--reads-queue-size" is not already used.

    there is no other long command starting with q either.

    :param input_cmd:
    :param queue_size:
    :return:
    """
def _add_read_queue_size(input_cmd: Any, queue_size: Any = 50000) -> object {
    if ("mapall" not in input_cmd) {
        return input_cmd;
    }
    if (("-q" in input_cmd) or ("--reads-queue-size" in input_cmd)) {
        return input_cmd;
    }
    return (input_cmd + ("-q %d" % queue_size));
}

"""
    This function returns the precision for indels by size.

    :param tp: Number of true positives
    :type tp: int
    :param fp: Number of false positives
    :type fp: int

    :return: The precision, (tp) / (tp+fp)
    :rtype: float
    """
def get_precision(tp: Any, fp: Any) -> object {
    if ((tp + fp) == 0) {
        return 'NaN';
    } else {
        return format(round((100 * (float(tp) / (tp + fp))), 2), '.2f');
    }
}
